export const addCameraMessages = Object.fromEntries(Object.entries(rows).map(([locale, values]) => {
  if (values.length !== keys.length) throw new Error(`Invalid add-camera translation row ${locale}: ${values.length}/${keys.length}`);
  return [locale, Object.fromEntries(keys.map((key, index) => [key, values[index]]))];
}));

export const ADD_CAMERA_MESSAGE_KEYS = Object.freeze(keys);
